import{_ as p,o as s,c as a,a2 as r}from"./chunks/framework.BXzK3EA4.js";const o="/assets/baremetal_apps.BNtLLQfF.jpg",e="/assets/vps_apps.DfAkE2VK.jpg",i="/assets/appcenter_apps.RkgRz2k8.jpg",n="/assets/app_landing_page.DupAJ0TG.jpg",l="/assets/app_config.B4i-lvDU.jpg",c="/assets/confirm_order.BVWkcv28.jpg",h=JSON.parse('{"title":"快速开始","description":"","frontmatter":{"title":"快速开始"},"headers":[],"relativePath":"app-center/guide/quick-start.md","filePath":"app-center/guide/quick-start.md","lastUpdated":1794381603000}'),g={name:"app-center/guide/quick-start.md"};function _(m,t,d,u,f,k){return s(),a("div",null,[...t[0]||(t[0]=[r('<h3 id="应用市场入口位置" tabindex="-1">应用市场入口位置 <a class="header-anchor" href="#应用市场入口位置" aria-label="Permalink to &quot;应用市场入口位置&quot;">​</a></h3><p>应用中心已在裸机云和 VPS 产品上线。您可以通过以下方式进入：</p><p><strong>方式一：从云产品菜单进入</strong></p><p>如果您已确定使用裸机云或 VPS，可以在网站顶部导航栏点击对应菜单，在下拉列表中找到“APPS”分类，选择需要的应用。</p><p><img src="'+o+'" alt="裸机云菜单中的应用入口"></p><p><img src="'+e+'" alt="VPS 菜单中的应用入口"></p><p><strong>方式二：从应用中心进入</strong></p><p>如果您想先浏览有哪些应用可选，可以点击导航栏的“应用中心”，查看全部应用列表。</p><p><img src="'+i+'" alt="应用中心入口"></p><h3 id="应用选购流程" tabindex="-1">应用选购流程 <a class="header-anchor" href="#应用选购流程" aria-label="Permalink to &quot;应用选购流程&quot;">​</a></h3><ol><li><p><strong>选择应用和配置</strong></p><p>进入应用落地页后，您可以看到应用的基本介绍。页面上提供了针对不同使用场景的配置套餐推荐，您也可以在 VPS 和裸机云之间切换选择。确定配置后，点击“立即购买”。</p><p><img src="'+n+'" alt="应用落地页"></p></li><li><p><strong>填写部署信息</strong></p><p>在弹出的购买窗口中，完成以下配置：</p><ul><li><strong>部署区域</strong>：选择服务器所在的地理位置（美洲、亚洲、欧洲）。</li><li><strong>主机名和主机密码</strong>：设置服务器的登录凭据，部署完成后可通过 SSH 登录服务器进行管理。</li><li><strong>应用参数</strong>：根据应用要求填写必要的配置参数（如数据库密码、域名等）。</li><li><strong>付款周期和数量</strong>：选择购买时长和数量。</li></ul><p>填写完成后，点击“去结算”。</p><p><img src="'+l+'" alt="填写部署信息"></p></li><li><p><strong>确认订单并完成支付</strong></p><p>在订单确认页核对信息，如有优惠券可在此使用，确认无误后完成支付。支付完成后进入账单页面，您可以在此查看本次购买的完整信息，包括服务器的详细配置参数。</p><p>完成支付后，系统将自动开始部署应用，整个过程预计在 1-3 分钟内完成。</p><p><img src="'+c+'" alt="确认订单"></p></li></ol><blockquote><p><strong>提示</strong></p><p>虚拟机启动后，应用需要约 1~3 分钟的初始化时间。请在部署完成后稍作等待，待应用完全加载后再进行访问，以确保获得最佳使用体验。</p></blockquote>',12)])])}const P=p(g,[["render",_]]);export{h as __pageData,P as default};
